    jayapay_ph_payout_private_key text NOT NULL,
    jayapay_ph_payout_public_key text NOT NULL,
    max_withdrawal_count integer NOT NULL,
    CONSTRAINT withdrawal_settings_jayapay_ph_payout_fee_type_check CHECK ((jayapay_ph_payout_fee_type >= 0)),
    CONSTRAINT withdrawal_settings_max_withdrawal_count_check CHECK ((max_withdrawal_count >= 0)),
    CONSTRAINT withdrawal_settings_minimum_product_quantity_check CHECK ((minimum_product_quantity >= 0))
);


